def HasScalarTailDiameter (s : ℕ → X) (ε : ℝ) : Prop :=
  ∀ f : X →L[ℂ] ℂ, ∃ N : ℕ, ∀ i ≥ N, ∀ j ≥ N,
    ‖f (s i) - f (s j)‖ ≤ ε * ‖f‖

